<?php require_once __DIR__.'/_helpers.php'; $current_page_override='v_log.php'; $basePath=base_url(); ?><!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Log Aktivitas - SiParkir</title><link rel="stylesheet" href="<?=e($basePath.'/asset/dashboard_admin.css')?>"><style>.role-tag{display:inline-block;padding:4px 9px;border-radius:8px;font-size:10px;font-weight:bold;text-transform:uppercase}.role-tag.admin{background:#edf5ff;color:#3978c7}.role-tag.petugas{background:#eefaf3;color:#58a875}.role-tag.owner{background:#fff9e8;color:#bd9336}</style></head><body><div class="layout"><?php include __DIR__.'/_sidebar.php'; ?><main class="main"><header class="header"><div><p class="small-title">PARKING MANAGEMENT</p><h1>Log Aktivitas</h1><p class="subtitle">Riwayat aktivitas seluruh pengguna (Admin, Petugas, Owner) di sistem.</p></div></header><section class="page-panel"><form class="toolbar" method="get" action="c_log.php"><div class="inline-form"><input class="search-box" name="q" value="<?=e($_GET['q']??'')?>" placeholder="Cari aktivitas, nama, atau username..."><input class="form-input date-input" type="date" name="tanggal" value="<?=e($_GET['tanggal']??'')?>"><select class="form-select status-select" name="role"><option value="">Semua Role</option><option value="admin" <?=($_GET['role']??'')==='admin'?'selected':''?>>Admin</option><option value="petugas" <?=($_GET['role']??'')==='petugas'?'selected':''?>>Petugas</option><option value="owner" <?=($_GET['role']??'')==='owner'?'selected':''?>>Owner</option></select><button class="btn-secondary">Filter</button></div><a class="btn-secondary" href="<?=e($basePath.'/controller/c_log.php')?>">Reset</a></form><div class="table-wrapper"><table class="data-table"><thead><tr><th>Waktu</th><th>Pengguna</th><th>Role</th><th>Aktivitas</th></tr></thead><tbody><?php if(empty($log)):?><tr><td colspan="4" class="empty">Belum ada aktivitas yang tercatat.</td></tr><?php else:foreach($log as $l):?><tr><td><?=e(tanggal_id($l['waktu_aktivitas']))?></td><td><strong><?=e($l['nama_lengkap'])?></strong><small class="subrow">@<?=e($l['username'])?></small></td><td><span class="role-tag <?=e($l['role'])?>"><?=e($l['role'])?></span></td><td><?=e($l['aktivitas'])?></td></tr><?php endforeach;endif;?></tbody></table></div><div class="list-footer"><span>Menampilkan <?=count($log)?> aktivitas terbaru</span><span class="muted">Data diambil dari tb_log_aktivitas</span></div></section><footer><span>© 2026 SiParkir</span><span>Sistem Informasi Parkir</span></footer></main></div></body></html>
